  const FRA19 = [[1820, "« Méditations poétiques » de Lamartine"], [1830, "« Le Rouge et le Noir » de Stendhal"], [1835, "« Le Père Goriot » de Balzac"], [1856, "« Les Contemplations » de Victor Hugo"], [1857, "« Madame Bovary » de Flaubert"], [1862, "« Les Misérables » de Victor Hugo"], [1885, "« Germinal » de Zola"], [1883, "« Une vie » de Maupassant"], [1873, "« Une saison en enfer » de Rimbaud"], [1866, "« Poèmes saturniens » de Verlaine"]];
  chrono("tle-francais", "La Négritude et la littérature africaine", AFR.map(([d, o]) => [d, `la parution de ${o}`]));
  chrono("tle-francais", "Le roman et les mouvements littéraires", [...FRA19, ...AFR.filter((x) => x[0] < 1990)].map(([d, o]) => [d, `la parution de ${o}`]));
  chrono("tle-francais", "Le théâtre classique", FRA17.map(([d, o]) => [d, `la parution de ${o}`]));
