  chrono("1ere-francais", "Le XVIIIe siècle : les Lumières", FRA18.map(([d, o]) => [d, `la parution de ${o}`]));
  chrono("1ere-francais", "Le XIXe siècle : romantisme et réalisme", FRA19.map(([d, o]) => [d, `la parution de ${o}`]));
  chrono("1ere-francais", "La Négritude et le théâtre africain", AFR.filter((x) => x[0] < 1990).map(([d, o]) => [d, `la parution de ${o}`]));
  chrono("2nde-francais", "Le récit : roman et nouvelle", [...AFR.filter((x) => x[1].match(/Enfant|Bouts|Aventure|Soleils|longue|Ventre|Murambi|Batouala|Docker|écarlate/)), [1831, "« Notre-Dame de Paris » de Victor Hugo"], [1857, "« Madame Bovary » de Flaubert"], [1885, "« Germinal » de Zola"]].map(([d, o]) => [d, `la parution de ${o}`]));
  const AUT = [[1606, "Corneille"], [1621, "La Fontaine"], [1622, "Molière"], [1639, "Racine"], [1689, "Montesquieu"], [1694, "Voltaire"], [1712, "Rousseau"], [1713, "Diderot"], [1799, "Balzac"], [1802, "Victor Hugo"], [1821, "Baudelaire"], [1840, "Zola"], [1906, "Senghor"], [1910, "Abdoulaye Sadji"], [1912, "Léon-Gontran Damas"], [1913, "Aimé Césaire"], [1923, "Ousmane Sembène"], [1927, "Ahmadou Kourouma"], [1928, "Cheikh Hamidou Kane"], [1929, "Mariama Bâ"], [1933, "Cheik Aliou Ndao"], [1946, "Boubacar Boris Diop"], [1968, "Fatou Diome"], [1990, "Mohamed Mbougar Sarr"]];
  chrono("tle-francais", "Méthodes : dissertation et commentaire", AUT.map(([d, n]) => [d, `la naissance de ${n}`]));
