  // =====================================================================================================
  // FRANÇAIS COLLÈGE (coef double) : moteur de conjugaison des 1er et 2e groupes, homophones
  // =====================================================================================================
  const V1 = ["parler", "chanter", "danser", "marcher", "aimer", "jouer", "regarder", "écouter", "travailler", "donner", "porter", "demander", "trouver", "montrer", "laver", "garder", "gagner", "chercher", "préparer", "raconter", "réparer", "dessiner", "cultiver", "visiter", "saluer", "goûter", "fermer", "pêcher"];
  const V2 = ["finir", "choisir", "réussir", "grandir", "remplir", "obéir", "réfléchir", "bâtir", "punir", "rougir", "nourrir", "applaudir", "agir", "établir", "réunir"];
  const PRO = ["je", "tu", "il", "nous", "vous", "ils"];
  const pron = (k, f) => (k === 0 && /^[aeéèêiouâh]/.test(f) ? "j'" : PRO[k] + " ") + f;
  const FT = {
    present: (v) => (v.endsWith("er") ? ["e", "es", "e", "ons", "ez", "ent"].map((x) => v.slice(0, -2) + x) : ["is", "is", "it", "issons", "issez", "issent"].map((x) => v.slice(0, -2) + x)),
    imparfait: (v) => { const b = v.endsWith("er") ? v.slice(0, -2) : v.slice(0, -2) + "iss"; return ["ais", "ais", "ait", "ions", "iez", "aient"].map((x) => b + x); },
    futur: (v) => ["ai", "as", "a", "ons", "ez", "ont"].map((x) => v + x),
    "passé simple": (v) => (v.endsWith("er") ? ["ai", "as", "a", "âmes", "âtes", "èrent"].map((x) => v.slice(0, -2) + x) : ["is", "is", "it", "îmes", "îtes", "irent"].map((x) => v.slice(0, -2) + x)),
    "conditionnel présent": (v) => ["ais", "ais", "ait", "ions", "iez", "aient"].map((x) => v + x),
    "subjonctif présent": (v) => { const b = v.endsWith("er") ? v.slice(0, -2) : v.slice(0, -2) + "iss"; return ["e", "es", "e", "ions", "iez", "ent"].map((x) => b + x); },
    "passé composé": (v) => { const pp = v.endsWith("er") ? v.slice(0, -2) + "é" : v.slice(0, -1); return ["ai", "as", "a", "avons", "avez", "ont"].map((x) => x + " " + pp); },
  };
  const VF = [...V1, ...V2];
  const fconj = (sid, ch, temps) => {
    add(sid, ch, (r) => { const t = pick(r, temps), v = pick(r, VF), k = ri(r, 0, 5), fs = FT[t](v), ok = pron(k, fs[k]);
      const alt = Object.keys(FT).filter((u) => u !== t).map((u) => pron(k, FT[u](v)[k]));
      return { q: `Conjugue « ${v} » au ${t}, à la personne « ${PRO[k]} » :`, ok, faux: autres(r, alt.concat(fs.map((f, i) => (i === k ? null : pron(k, f))).filter(Boolean)), ok), e: `${v} au ${t} : ${fs.map((f, i) => pron(i, f)).join(", ")}.` }; });
    add(sid, ch, (r) => { const v = pick(r, VF), k = ri(r, 0, 5), ts = mix(r, temps.length >= 4 ? temps : [...temps, ...Object.keys(FT).filter((u) => !temps.includes(u))]).slice(0, 4), t = ts[0], f = pron(k, FT[t](v)[k]); if (ts.some((u) => u !== t && FT[u](v)[k] === FT[t](v)[k])) return null;
      return { q: `À quel temps est conjugué « ${f} » ?`, ok: t, faux: ts.slice(1), e: `${f} : ${v} au ${t}.` }; });
    add(sid, ch, (r) => { const t = pick(r, temps), v = pick(r, VF), k = ri(r, 0, 5), fs = FT[t](v), suj = ["Je", "Tu", pick(r, ["Il", "Elle", "Awa", "Mon frère"]), "Nous", "Vous", pick(r, ["Ils", "Elles", "Les élèves"])][k], adv = { present: "maintenant", imparfait: "autrefois", futur: "demain", "passé simple": "ce jour-là", "conditionnel présent": "si je pouvais,", "subjonctif présent": "il faut que", "passé composé": "hier" }[t];
      const ok = fs[k], phr = t === "subjonctif présent" ? `Il faut que ${(k === 0 && /^[aeéèêiouâh]/.test(ok) ? "j'" : suj.toLowerCase() + " ")}___ (${v}).` : `${t === "conditionnel présent" ? "Avec plus de temps, " + suj.toLowerCase() : suj} ___ (${v}) ${t === "conditionnel présent" ? "davantage" : adv}.`;
      return { q: `Complète au ${t} : ${phr}`, ok, faux: autres(r, Object.keys(FT).filter((u) => u !== t).map((u) => FT[u](v)[k]).concat(fs.filter((x, i) => i !== k)), ok), e: `${v} au ${t}, ${PRO[k]} : ${ok}.` }; });
  };
  fconj("5e-francais", "Conjugaison : passé composé, passé simple, futur", ["passé composé", "passé simple", "futur"]);
  fconj("4e-francais", "Conjugaison : conditionnel et subjonctif", ["conditionnel présent", "subjonctif présent"]);
  fconj("3e-francais", "Conjugaison : futur, passé simple, subjonctif, conditionnel", ["futur", "passé simple", "subjonctif présent", "conditionnel présent"]);
  fconj("6e-francais", "Conjugaison : présent, imparfait, futur", ["present", "imparfait", "futur"]);
  const NOMH = ["Awa", "Moussa", "Fatou", "Ibrahima", "Khady", "Ousmane", "Aminata", "Cheikh", "Mariama", "Lamine"];
  const HOMO = [
    ["a / à", [["${n} ___ un vélo neuf.", "a"], ["${n} va ___ l'école.", "à"], ["${n} ___ fini ses devoirs.", "a"], ["${n} pense ___ sa mère.", "à"], ["${n} ___ peur du noir.", "a"], ["${n} habite ___ Thiès.", "à"], ["${n} ___ reçu une lettre.", "a"], ["${n} parle ___ son voisin.", "à"]], ["a", "à", "as", "ah"]],
    ["et / est", [["${n} ___ malade aujourd'hui.", "est"], ["${n} ___ son frère jouent.", "et"], ["${n} ___ parti tôt.", "est"], ["Le riz ___ le poisson sont prêts, dit ${n}.", "et"], ["${n} ___ très gentille.", "est"], ["${n} lit ___ écrit.", "et"]], ["et", "est", "es", "ai"]],
    ["son / sont", [["${n} range ___ cartable.", "son"], ["Les amis de ${n} ___ arrivés.", "sont"], ["${n} prête ___ livre.", "son"], ["Les cousins de ${n} ___ à Dakar.", "sont"], ["${n} cherche ___ stylo.", "son"], ["Les parents de ${n} ___ fiers.", "sont"]], ["son", "sont", "sons", "sonts"]],
    ["ou / où", [["${n} prend du thé ___ du café ?", "ou"], ["${n} se demande ___ est sa clé.", "où"], ["La maison ___ vit ${n} est grande.", "où"], ["${n} viendra lundi ___ mardi.", "ou"], ["${n} sait ___ aller.", "où"]], ["ou", "où", "houx", "août"]],
    ["ces / ses", [["${n} a perdu ___ lunettes.", "ses"], ["Regarde ___ nuages, dit ${n}.", "ces"], ["${n} lave ___ habits.", "ses"], ["${n} achète ___ mangues-là.", "ces"]], ["ces", "ses", "c'est", "s'est"]],
    ["on / ont", [["Les amis de ${n} ___ gagné le match.", "ont"], ["Avec ${n}, ___ va au marché.", "on"], ["Les voisins de ${n} ___ une voiture.", "ont"], ["${n} dit qu'___ part demain.", "on"]], ["on", "ont", "on n'", "hon"]],
  ];
  for (const [nom, phr, opts] of HOMO) add("5e-francais", "Accords et homophones", (r) => { const [p, ok] = pick(r, phr), n = pick(r, NOMH); return { q: `${nom} : ${p.replace("${n}", n)}`, ok, faux: opts.filter((x) => x !== ok).slice(0, 3), e: { "a / à": "a = verbe avoir (on peut dire « avait ») ; à = préposition.", "et / est": "est = verbe être (« était ») ; et = conjonction (« et puis »).", "son / sont": "sont = verbe être (« étaient ») ; son = déterminant (« mon »).", "ou / où": "ou = « ou bien » ; où = lieu ou question.", "ces / ses": "ses = les siens ; ces = ceux-là, qu'on montre.", "on / ont": "ont = verbe avoir (« avaient ») ; on = pronom (« il »)." }[nom] }; });
  add("5e-francais", "Fonctions : COD, COI, groupe nominal", (r) => { const n = pick(r, NOMH), [ph, gr0, ok] = pick(r, [["mange une mangue", "une mangue", "COD"], ["parle à son professeur", "à son professeur", "COI"], ["écrit une lettre", "une lettre", "COD"], ["pense à ses vacances", "à ses vacances", "COI"], ["répond à la question", "à la question", "COI"], ["achète du pain", "du pain", "COD"], ["obéit à ses parents", "à ses parents", "COI"], ["lave la voiture", "la voiture", "COD"], ["se souvient de son village", "de son village", "COI"], ["regarde le match", "le match", "COD"], ["est content", "content", "attribut du sujet"], ["devient médecin", "médecin", "attribut du sujet"], ["part le matin", "le matin", "complément circonstanciel"], ["joue dans la cour", "dans la cour", "complément circonstanciel"]]);
    return { q: `Fonction de « ${gr0} » : ${n} ${ph}.`, ok, faux: autres(r, ["COD", "COI", "attribut du sujet", "complément circonstanciel", "sujet"], ok), e: { COD: "COD : répond à « quoi ? » sans préposition.", COI: "COI : répond à « à quoi / de quoi ? », avec préposition.", "attribut du sujet": "Attribut : après un verbe d'état (être, devenir, paraître).", "complément circonstanciel": "CC : indique le lieu, le temps, la manière ; on peut le déplacer ou le supprimer." }[ok] }; });

  // =====================================================================================================
  // SVT 1re (coef 6 en S2) : calculs tirés au hasard sur chaque chapitre
  // =====================================================================================================
  const SV = "1ere-svt", TP = "Tectonique des plaques et géologie", NR = "Système nerveux et réflexes", MU = "Le muscle et l'énergie", MI = "Milieu intérieur : sang, glycémie, rein", RM = "Roches magmatiques et métamorphiques";
  add(SV, TP, (r) => { const d = ri(r, 20, 1500), A = ri(r, 2, 80), v = d / (10 * A); return { q: `Un basalte situé à ${F(d)} km de l'axe de la dorsale a ${A} millions d'années. Vitesse moyenne d'expansion (d'un côté) :`, ok: `${nf(v, 2)} cm/an`, faux: autres(r, [`${nf(v * 10, 2)} cm/an`, `${nf(v / 10, 3)} cm/an`, `${nf(v * 2, 2)} cm/an`, `${nf(A / d, 3)} cm/an`], `${nf(v, 2)} cm/an`), e: `${F(d)} km = ${F(d * 1e5)} cm ; ÷ ${A} × 10⁶ ans = ${nf(v, 2)} cm/an.` }; });
  add(SV, TP, (r) => { const v = ri(r, 1, 10), d = ri(r, 10, 1200), A = d / (10 * v); return { q: `La dorsale s'ouvre de ${v} cm/an de chaque côté. Âge du plancher océanique à ${F(d)} km de l'axe :`, ok: `${nf(A, 1)} Ma`, faux: autres(r, [`${nf(A * 10, 1)} Ma`, `${nf(A / 10, 2)} Ma`, `${nf(A / 2, 1)} Ma`, `${nf(d * v, 0)} Ma`], `${nf(A, 1)} Ma`), e: `t = d / v = ${F(d * 1e5)} cm / ${v} cm/an = ${nf(A, 1)} millions d'années.` }; });
  add(SV, TP, (r) => { const dt = ri(r, 4, 120), vp = 6, vs = 3.5, d = (dt * vp * vs) / (vp - vs); return { q: `Les ondes P (6 km/s) arrivent ${dt} s avant les ondes S (3,5 km/s). Distance du foyer :`, ok: `${nf(d, 0)} km`, faux: autres(r, [`${nf(dt * vp, 0)} km`, `${nf(dt * vs, 0)} km`, `${nf(dt * (vp - vs), 0)} km`, `${nf(d * 2, 0)} km`], `${nf(d, 0)} km`), e: `d = Δt × vP × vS / (vP − vS) = ${dt} × 6 × 3,5 / 2,5 = ${nf(d, 0)} km.` }; });
  add(SV, TP, (r) => { const g = pick(r, [2, 2.5, 3, 3.5]), z = ri(r, 1, 30), T0 = ri(r, 20, 30), T = T0 + g * 10 * z; return { q: `Gradient géothermique ${nf(g, 1)} °C pour 100 m, ${T0} °C en surface. Température à ${z} km de profondeur :`, ok: `${nf(T, 0)} °C`, faux: autres(r, [`${nf(T0 + g * z, 0)} °C`, `${nf(g * 10 * z, 0)} °C`, `${nf(T0 + g * 100 * z, 0)} °C`, `${nf(T + 100, 0)} °C`], `${nf(T, 0)} °C`), e: `${nf(g, 1)} °C/100 m = ${nf(g * 10, 0)} °C/km : ${T0} + ${nf(g * 10, 0)} × ${z} = ${nf(T, 0)} °C.` }; });
  add(SV, TP, (r) => { const v = ri(r, 2, 9), ang = pick(r, [30, 45, 60]), t = ri(r, 1, 20), L = v * t * 10, z = L * Math.sin((ang * Math.PI) / 180); return { q: `Une plaque plonge en subduction à ${v} cm/an, avec un angle de ${ang}°. Profondeur atteinte par un point de la plaque en ${t} millions d'années :`, ok: `${nf(z, 0)} km`, faux: autres(r, [`${nf(L, 0)} km`, `${nf(L * Math.cos((ang * Math.PI) / 180), 0)} km`, `${nf(z / 10, 1)} km`, `${nf(z * 2, 0)} km`], `${nf(z, 0)} km`), e: `Longueur parcourue ${nf(L, 0)} km ; profondeur = ${nf(L, 0)} × sin ${ang}° ≈ ${nf(z, 0)} km.` }; });
  add(SV, RM, (r) => { const rho = pick(r, [2700, 2800, 2900, 3000, 3300]), h = ri(r, 2, 60), P = (rho * 10 * h * 1000) / 1e6; return { q: `Pression lithostatique à ${h} km de profondeur (ρ = ${F(rho)} kg/m³, g = 10 N/kg) :`, ok: `${nf(P, 0)} MPa`, faux: autres(r, [`${nf(P / 1000, 2)} MPa`, `${nf(P * 10, 0)} MPa`, `${nf(P / 10, 1)} MPa`, `${nf(rho * h, 0)} MPa`], `${nf(P, 0)} MPa`), e: `P = ρ g h = ${F(rho)} × 10 × ${F(h * 1000)} = ${nf(P, 0)} × 10⁶ Pa = ${nf(P, 0)} MPa (${nf(P / 1000, 2)} GPa).` }; });
  add(SV, RM, (r) => { const rho = pick(r, [2700, 2800, 3000]), P = ri(r, 2, 15) * 100, h = (P * 1e6) / (rho * 10) / 1000; return { q: `Un minéral s'est formé sous ${F(P)} MPa. À quelle profondeur environ (ρ = ${F(rho)} kg/m³, g = 10 N/kg) ?`, ok: `${nf(h, 1)} km`, faux: autres(r, [`${nf(h * 10, 1)} km`, `${nf(h / 10, 2)} km`, `${nf(h * 2, 1)} km`, `${nf(P / 10, 0)} km`], `${nf(h, 1)} km`), e: `h = P / (ρ g) = ${F(P)} × 10⁶ / (${F(rho)} × 10) ≈ ${nf(h, 1)} km.` }; });
  classe(SV, RM, { "une roche plutonique, à structure grenue": ["le granite", "le gabbro", "la diorite", "la granodiorite"], "une roche volcanique, à structure microlitique": ["le basalte", "l'andésite", "la rhyolite", "la trachyte"], "une roche métamorphique": ["le gneiss", "le micaschiste", "le marbre", "le schiste bleu", "l'éclogite", "le quartzite"] }, (g) => `Laquelle est ${g} ?`, null);
  termes(SV, RM, [["la structure grenue", "une roche entièrement cristallisée en gros cristaux, refroidie lentement en profondeur"], ["la structure microlitique", "une roche avec du verre et de petits cristaux, refroidie vite en surface"], ["le métamorphisme", "la transformation d'une roche à l'état solide sous l'effet de la pression et de la température"], ["la schistosité", "le débit en feuillets d'une roche, perpendiculaire à la contrainte"], ["la foliation", "l'alternance de lits clairs et sombres dans une roche métamorphique (gneiss)"], ["l'andalousite", "le silicate d'alumine des basses pressions"], ["le disthène", "le silicate d'alumine des hautes pressions"], ["la sillimanite", "le silicate d'alumine des hautes températures"], ["la glaucophane", "le minéral bleu des hautes pressions et basses températures (subduction)"], ["l'anatexie", "la fusion partielle d'une roche de la croûte qui donne un magma granitique"], ["le métamorphisme de contact", "la transformation des roches autour d'un massif magmatique chaud"]]);
  add(SV, NR, (r) => { const d = ri(r, 20, 150), dt = ri(r, 2, 40) / 4; const v = d / dt; return { q: `Deux électrodes réceptrices sont distantes de ${d} mm. Le potentiel d'action arrive sur la seconde ${nf(dt, 2)} ms après la première. Vitesse de conduction :`, ok: `${nf(v, 1)} m/s`, faux: autres(r, [`${nf(v * 10, 1)} m/s`, `${nf(v / 10, 2)} m/s`, `${nf(dt / d, 3)} m/s`, `${nf(d * dt, 1)} m/s`], `${nf(v, 1)} m/s`), e: `v = d / Δt = ${d} mm / ${nf(dt, 2)} ms = ${nf(v, 1)} m/s (1 mm/ms = 1 m/s).` }; });
  add(SV, NR, (r) => { const v = pick(r, [1, 2, 10, 30, 50, 80, 100, 120]), d = ri(r, 10, 150) / 100, t = (d / v) * 1000; return { q: `Un message nerveux parcourt ${nf(d, 2)} m à ${v} m/s. Durée du trajet :`, ok: `${nf(t, 1)} ms`, faux: autres(r, [`${nf(t / 1000, 4)} ms`, `${nf(t * 10, 1)} ms`, `${nf(d * v, 1)} ms`, `${nf(t / 2, 1)} ms`], `${nf(t, 1)} ms`), e: `t = d / v = ${nf(d, 2)} / ${v} s = ${nf(t, 1)} ms.` }; });
  add(SV, NR, (r) => { const n = ri(r, 3, 60), t = pick(r, [10, 20, 50, 100, 200]), f = (n / t) * 1000; return { q: `On enregistre ${n} potentiels d'action en ${t} ms sur une fibre. Fréquence :`, ok: `${nf(f, 0)} Hz`, faux: autres(r, [`${nf(n / t, 2)} Hz`, `${nf(f / 10, 0)} Hz`, `${nf(t / n, 2)} Hz`, `${nf(f * 2, 0)} Hz`], `${nf(f, 0)} Hz`), e: `f = ${n} / ${t / 1000} s = ${nf(f, 0)} Hz. Un message nerveux est codé en fréquence de potentiels d'action.` }; });
  add(SV, NR, (r) => { const d1 = ri(r, 30, 100) / 100, d2 = ri(r, 30, 100) / 100, v = pick(r, [50, 60, 80, 100]), k = ri(r, 1, 3), t = ((d1 + d2) / v) * 1000 + 0.5 * k; return { q: `Réflexe : trajet sensitif ${nf(d1, 2)} m, trajet moteur ${nf(d2, 2)} m, vitesse ${v} m/s, ${k} synapse${k > 1 ? "s" : ""} de 0,5 ms chacune. Temps de réflexe :`, ok: `${nf(t, 1)} ms`, faux: autres(r, [`${nf(((d1 + d2) / v) * 1000, 1)} ms`, `${nf(t + 0.5, 1)} ms`, `${nf((d1 / v) * 1000 + 0.5 * k, 1)} ms`, `${nf(t * 2, 1)} ms`], `${nf(t, 1)} ms`), e: `(${nf(d1, 2)} + ${nf(d2, 2)}) / ${v} s = ${nf(((d1 + d2) / v) * 1000, 1)} ms, + ${k} × 0,5 ms = ${nf(t, 1)} ms. ${k === 1 ? "Une seule synapse : réflexe monosynaptique (myotatique)." : "Plusieurs synapses : réflexe polysynaptique."}` }; });
  classe(SV, NR, { "un élément de l'arc réflexe myotatique": ["le fuseau neuromusculaire (récepteur)", "la fibre sensitive", "le motoneurone", "la moelle épinière (centre)", "le muscle étiré (effecteur)"], "sans rôle dans l'arc réflexe myotatique": ["le cortex visuel", "le cervelet", "la rétine", "le nerf optique"] }, (g) => `Lequel est ${g} ?`, null);
