  const MOD = [["Il est certain qu'il a oublié son livre.", "He must have forgotten his book."], ["Il est impossible qu'elle ait vu le film.", "She can't have seen the film."], ["Il a peut-être raté le bus.", "He may have missed the bus."], ["Tu aurais dû travailler plus.", "You should have worked harder."], ["Ils auraient pu gagner.", "They could have won."], ["Elle n'aurait pas dû partir.", "She shouldn't have left."], ["Il a sûrement pris le train.", "He must have taken the train."], ["Ils n'ont sûrement pas compris.", "They can't have understood."], ["Nous aurions dû appeler.", "We should have called."], ["Elle a pu se perdre.", "She might have got lost."], ["Tu n'avais pas besoin de venir (et tu es venu).", "You needn't have come."], ["Il aurait pu se blesser.", "He could have hurt himself."]];
