  const ADJ = ["hot", "tired", "difficult", "tall", "expensive", "cold", "interesting", "late", "noisy", "beautiful"], NN = [["a hot day", "hot"], ["an interesting book", "interesting"], ["a difficult exam", "difficult"], ["an expensive phone", "expensive"], ["a long journey", "long"], ["a noisy class", "noisy"], ["good friends", "good"], ["bad weather", "bad"]];
  add(A1, "Structures : passif, so...that, the more", (r) => { const s = r() < 0.5; if (s) { const a = pick(r, ADJ); return { q: `Complete: It was ___ ${a} that we stayed at home.`, ok: "so", faux: ["such", "such a", "too"], e: "so + adjectif (sans nom) … that." }; } const [np] = pick(r, NN), ok = "such"; return { q: `Complete: It was ___ ${np} that we stayed at home.`, ok, faux: ["so", "so a", "too"], e: "such + (a/an) + adjectif + nom … that." }; });
  const CMP = [["big", "bigger", "the biggest"], ["hot", "hotter", "the hottest"], ["small", "smaller", "the smallest"], ["happy", "happier", "the happiest"], ["easy", "easier", "the easiest"], ["good", "better", "the best"], ["bad", "worse", "the worst"], ["far", "farther", "the farthest"], ["interesting", "more interesting", "the most interesting"], ["expensive", "more expensive", "the most expensive"], ["beautiful", "more beautiful", "the most beautiful"], ["tall", "taller", "the tallest"], ["fast", "faster", "the fastest"], ["dangerous", "more dangerous", "the most dangerous"], ["cheap", "cheaper", "the cheapest"], ["heavy", "heavier", "the heaviest"]];
  add(A1, "Structures : passif, so...that, the more", (r) => { const [a, c, s] = pick(r, CMP), sup = r() < 0.5, ok = sup ? s : c; return { q: `${sup ? "Superlative" : "Comparative"} of « ${a} » :`, ok, faux: autres(r, [sup ? c : s, `more ${a}`, `${a}er`, `the more ${a}`, `most ${a}`].filter((x) => x !== ok), ok), e: `${a} → ${c} → ${s}.` }; });
  add(A1, "Structures : passif, so...that, the more", (r) => { const [[a, c], [b, d]] = mix(r, CMP.filter((x) => !x[1].startsWith("more") && !["good", "bad", "far"].includes(x[0]))).slice(0, 2).map((x) => [x[0], x[1]]); const ok = `the ${c} … the ${d}`; return { q: `Complete with « ${a} » and « ${b} »: « ___ the box is, ___ it looks. »`, ok, faux: [`the more ${a} … the more ${b}`, `more ${c} … more ${d}`, `the ${c} … ${d}`], e: "Structure : the + comparatif …, the + comparatif … (plus… plus…)." }; });
  termes(A1, "Connecteurs et vocabulaire", [["however", "cependant"], ["therefore", "par conséquent"], ["although", "bien que"], ["despite", "malgré"], ["whereas", "alors que (opposition)"], ["moreover", "de plus"], ["unless", "à moins que"], ["meanwhile", "pendant ce temps"], ["nevertheless", "néanmoins"], ["otherwise", "sinon"], ["as long as", "tant que, du moment que"], ["so that", "afin que"], ["whether", "si (alternative)"], ["thus", "ainsi"], ["owing to", "en raison de"]].map(([e, f]) => [`« ${e} »`, f]));

